/* xx_pakleo_extractor.c - search raw data for PAKLEO.
 *
 * Scans for:
 *   4C 45 4F 4C 5A 57 20 2D 20 28 63 29 20 4C 65 6F 6E 61 72 64 75 73 20 4C 65 6F 6E 61 72 64 69 20 31 39 39 33 at +0  ("LEOLZW - (c) Leonardus Leonardi 1993")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the pakleo reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/pakleo/xx_pakleo.h"

static const uint8_t k_anchor0[] = { 0x4C, 0x45, 0x4F, 0x4C, 0x5A, 0x57, 0x20, 0x2D, 0x20, 0x28, 0x63, 0x29, 0x20, 0x4C, 0x65, 0x6F, 0x6E, 0x61, 0x72, 0x64, 0x75, 0x73, 0x20, 0x4C, 0x65, 0x6F, 0x6E, 0x61, 0x72, 0x64, 0x69, 0x20, 0x31, 0x39, 0x39, 0x33 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_PAKLEO };

static Abstractformat *xx_pakleo_search_open(xx_io_device *window) {
    xx_pakleo *reader = xx_pakleo_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_pakleo_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_pakleo_free((xx_pakleo *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_pakleo_search_open, xx_pakleo_search_close
};

static xx_format_search_state *xx_pakleo_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_pakleo_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_pakleo_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_pakleo_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_pakleo_extractor = {
    xx_pakleo_create_format_search,
    xx_pakleo_get_current_format_info,
    xx_pakleo_format_search_find_next,
    xx_pakleo_free_format_search
};
